import math

def mean_duration(values):
    if not values:
        return None
    for value in values:
        if isinstance(value, bool):
            raise ValueError('Boolean duration is invalid')
        if not isinstance(value, (int, float)):
            raise ValueError('Duration must be numeric')
        if not math.isfinite(value) or value < 0:
            raise ValueError('Duration must be finite and non-negative')
    return sum(values) / len(values)

print(mean_duration([2, 5, 3, 4, 6, 1]))
print(mean_duration([]))
# Expected: 3.5, then None

def summary(values):
    mean = mean_duration(values)
    return {'count': len(values), 'total': sum(values),
            'mean': mean}

print(summary([]))
# {'count': 0, 'total': 0, 'mean': None}
print(summary([0]))
# {'count': 1, 'total': 0, 'mean': 0.0}
